      'ai.connected': 'AI ansluten',
      'ai.convert_estimate': 'Konvertera och kalkylera',
      'ai.currency_label': 'Valuta',
      'ai.describe_placeholder': 'Beskriv ditt projekt...\n\nExempel: ',
      'ai.dismiss': 'Stäng',
      'ai.drop_file': 'Släpp din fil här, eller klicka för att bläddra',
      'ai.estimate_complete': 'Kalkyl genererad',
      'ai.estimate_complete_msg': '{{count}} poster genererade',
