      'ai.estimate_subtitle': 'Skapa en kalkyl från valfri källa',
      'ai.estimate_title': 'AI-kalkyl',
      'ai.excel_hint': 'Fungerar bäst med kolumner: Beskrivning, Enhet, Mängd, Pris/À-pris.',
